// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract Slot0Writer {
    address slot0;
    function setSlot0(address x) external {
        slot0 = x;
    }
}

contract InvMutTest is Test {
    Proxy c;
    Slot0Writer writer;

    function setUp() public {
        c = new Proxy();
        writer = new Slot0Writer();
    }

    function testFuzz_forwardCannotOverwriteProxyStorage(address newOwner) public {
        bytes32 before = vm.load(address(c), bytes32(uint256(0)));
        address curOwner = address(uint160(uint256(before)));
        vm.assume(newOwner != address(0));
        vm.assume(newOwner != curOwner);
        vm.assume(newOwner != address(c));
        vm.assume(newOwner != address(writer));
        c.forward(address(writer), abi.encodeWithSignature("setSlot0(address)", newOwner));
        bytes32 afterVal = vm.load(address(c), bytes32(uint256(0)));
        assertEq(before, afterVal);
    }
}
